// Settings for tools/to-ts.mjs. This file is where Phase 1 typing happens:
// add an interface to src/types.ts, then map a top-level variable to it here.

export default {
  // Prepended to src/game.ts. Keep the line count stable: the doc's
  // "game.ts line = game.js line + 6" rule depends on it.
  header: [
    '// GENERATED by `npm run port` from the HTML build. Do not edit by hand:',
    '// changes here are overwritten on the next port. See tools/port-config.mjs.',
    '// Line N of this file is line N - 6 of legacy/current/game.js.',
    "import * as THREE from 'three';",
    "import MODEL_JSON from './assets/bunny-model.json?raw';",
    "import type { Player, Item, Theme, Monster } from './types';"
  ],

  // Top-level `const`/`let` name -> type. Everything else built from an
  // object or array literal is typed `any` / `any[]`.
  annotations: {
    P: 'Player',
    ITEMS: 'Item[]',
    THD: 'Theme',
    ARCS: 'Partial<Theme>[]',
    MONS: 'Monster[]'
  },

  // Exact-text substitutions. A `find` that disappears from a new version is
  // reported by the port so it can be checked by hand.
  replace: [
    { find: "JSON.parse($('mdata').textContent)", with: 'JSON.parse(MODEL_JSON)' }
  ]
};
